<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Sorting Visualizer</title>
<style>
  :root{
    --bg:#0e1116;
    --panel:#161b22;
    --edge:#2a313c;
    --fg:#e6edf3;
    --muted:#8b949e;
    --bar:#3b82f6;
    --bar2:#60a5fa;
    --cmp:#f59e0b;
    --swap:#ef4444;
    --ok:#22c55e;
  }
  *{box-sizing:border-box}
  html,body{height:100%}
  body{
    margin:0;
    background:radial-gradient(1200px 600px at 50% -10%,#18202b,var(--bg));
    color:var(--fg);
    font:14px/1.45 ui-sans-serif,system-ui,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
    display:flex;
    flex-direction:column;
    align-items:center;
    padding:24px 16px 32px;
    gap:18px;
  }
  h1{
    margin:0;
    font-size:18px;
    font-weight:600;
    letter-spacing:.3px;
  }
  h1 span{color:var(--muted);font-weight:400}
  #panel{
    display:flex;
    flex-wrap:wrap;
    gap:10px;
    align-items:center;
    justify-content:center;
    background:var(--panel);
    border:1px solid var(--edge);
    border-radius:10px;
    padding:10px 14px;
  }
  button{
    appearance:none;
    background:#1f2632;
    color:var(--fg);
    border:1px solid var(--edge);
    border-radius:7px;
    padding:8px 14px;
    font:inherit;
    font-weight:500;
    cursor:pointer;
    transition:background .15s,border-color .15s,transform .05s;
  }
  button:hover{background:#273040;border-color:#3d465580}
  button:active{transform:translateY(1px)}
  button:disabled{opacity:.5;cursor:not-allowed}
  #sort{border-color:#2f6fd0;background:#1b2c46}
  #sort:hover{background:#22385a}
  label{color:var(--muted);display:flex;gap:8px;align-items:center}
  input[type=range]{accent-color:var(--bar);width:130px}
  #wrap{
    width:min(1000px,100%);
    background:var(--panel);
    border:1px solid var(--edge);
    border-radius:12px;
    padding:14px;
  }
  #bars{
    display:flex;
    align-items:flex-end;
    gap:2px;
    height:340px;
    width:100%;
  }
  .bar{
    flex:1 1 0;
    min-width:2px;
    background:linear-gradient(180deg,var(--bar2),var(--bar));
    border-radius:3px 3px 0 0;
    transition:height .06s linear, background .06s linear;
  }
  .bar.cmp{background:linear-gradient(180deg,#fbbf24,var(--cmp))}
  .bar.swap{background:linear-gradient(180deg,#f87171,var(--swap))}
  .bar.done{background:linear-gradient(180deg,#4ade80,var(--ok))}
  #status{color:var(--muted);font-variant-numeric:tabular-nums}
  #status b{color:var(--fg);font-weight:600}
</style>
</head>
<body>

<h1>Sorting Visualizer <span>— bubble sort, one step at a time</span></h1>

<div id="panel">
  <button id="sort">Sort</button>
  <button id="shuffle">Shuffle</button>
  <button id="reset">Reset</button>
  <label>Size <input id="size" type="range" min="5" max="120" value="45"></label>
  <label>Speed <input id="speed" type="range" min="1" max="200" value="60"></label>
</div>

<div id="wrap">
  <div id="bars"></div>
</div>

<div id="status">steps <b id="steps">0</b> · comparisons <b id="cmps">0</b> · swaps <b id="swaps">0</b> · <b id="state">idle</b></div>

<script>
(function () {
  "use strict";

  var barsEl   = document.getElementById("bars");
  var stepsEl  = document.getElementById("steps");
  var cmpsEl   = document.getElementById("cmps");
  var swapsEl  = document.getElementById("swaps");
  var stateEl  = document.getElementById("state");
  var sizeEl   = document.getElementById("size");
  var speedEl  = document.getElementById("speed");

  var arr = [];
  var original = [];
  var bars = [];

  // bubble-sort cursor
  var i = 0, j = 0, swappedThisPass = false, finished = false;
  var lastA = -1, lastB = -1, lastSwap = false;

  var steps = 0, comparisons = 0, swaps = 0;
  var running = false, timer = null;

  function randomArray(n) {
    var a = [];
    for (var k = 0; k < n; k++) a.push(1 + Math.floor(Math.random() * 100));
    return a;
  }

  function resetCursor() {
    i = 0; j = 0; swappedThisPass = false;
    finished = isSorted(arr);
    lastA = lastB = -1; lastSwap = false;
    steps = comparisons = swaps = 0;
  }

  function isSorted(a) {
    for (var k = 1; k < a.length; k++) if (a[k - 1] > a[k]) return false;
    return true;
  }

  function build() {
    barsEl.innerHTML = "";
    bars = [];
    for (var k = 0; k < arr.length; k++) {
      var el = document.createElement("div");
      el.className = "bar";
      barsEl.appendChild(el);
      bars.push(el);
    }
    draw();
  }

  function draw() {
    var max = 1;
    for (var k = 0; k < arr.length; k++) if (arr[k] > max) max = arr[k];
    for (var k2 = 0; k2 < arr.length; k2++) {
      var el = bars[k2];
      if (!el) continue;
      el.style.height = Math.max(2, Math.round((arr[k2] / max) * 100)) + "%";
      el.title = String(arr[k2]);
      var cls = "bar";
      if (finished) cls += " done";
      else if (k2 === lastA || k2 === lastB) cls += lastSwap ? " swap" : " cmp";
      el.className = cls;
    }
    stepsEl.textContent = steps;
    cmpsEl.textContent = comparisons;
    swapsEl.textContent = swaps;
    stateEl.textContent = finished ? "sorted" : (running ? "sorting" : "idle");
  }

  // Exactly one comparison (and possible swap) per call.
  // Returns true when the array is fully sorted.
  function sortStep() {
    var n = arr.length;
    if (n < 2) { finished = true; return true; }
    if (finished) return true;

    // end of a pass?
    if (j >= n - 1 - i) {
      if (!swappedThisPass) { finished = true; lastA = lastB = -1; return true; }
      i++; j = 0; swappedThisPass = false;
      if (i >= n - 1) { finished = true; lastA = lastB = -1; return true; }
    }

    steps++;
    comparisons++;
    lastA = j; lastB = j + 1; lastSwap = false;

    if (arr[j] > arr[j + 1]) {
      var t = arr[j]; arr[j] = arr[j + 1]; arr[j + 1] = t;
      swaps++;
      swappedThisPass = true;
      lastSwap = true;
    }
    j++;

    if (j >= n - 1 - i && !swappedThisPass) { finished = true; }
    return finished;
  }

  function stop() {
    running = false;
    if (timer !== null) { clearInterval(timer); timer = null; }
    draw();
  }

  function run() {
    if (running) { stop(); return; }
    if (finished) return;
    running = true;
    var delay = Math.max(0, 205 - Number(speedEl.value));
    timer = setInterval(function () {
      var batch = 1 + Math.floor(Number(speedEl.value) / 40);
      for (var k = 0; k < batch; k++) {
        if (sortStep()) { draw(); stop(); return; }
      }
      draw();
    }, delay);
  }

  function shuffle() {
    stop();
    for (var k = arr.length - 1; k > 0; k--) {
      var r = Math.floor(Math.random() * (k + 1));
      var t = arr[k]; arr[k] = arr[r]; arr[r] = t;
    }
    original = arr.slice();
    resetCursor();
    draw();
  }

  function reset() {
    stop();
    arr = original.slice();
    resetCursor();
    build();
  }

  function regenerate(n) {
    stop();
    arr = randomArray(n);
    original = arr.slice();
    resetCursor();
    build();
  }

  document.getElementById("sort").addEventListener("click", run);
  document.getElementById("shuffle").addEventListener("click", shuffle);
  document.getElementById("reset").addEventListener("click", reset);
  sizeEl.addEventListener("input", function () { regenerate(Number(sizeEl.value)); });

  regenerate(Number(sizeEl.value));

  window.viz = {
    array: function () { return arr.slice(); },
    setArray: function (a) {
      stop();
      arr = Array.prototype.slice.call(a).map(Number);
      original = arr.slice();
      resetCursor();
      build();
      return arr.slice();
    },
    sortStep: function () {
      var done = sortStep();
      draw();
      return done;
    },
    sorted: function () { return isSorted(arr); },
    shuffle: shuffle,
    reset: reset
  };
})();
</script>
</body>
</html>
